<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientDefaultMaxAgeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDefaultMaxAgeAccessor trait.
 *
 * Covers null default, string/VO assignment via withDefaultMaxAge,
 * getDefaultMaxAge/defaultMaxAge accessors, and isDefaultMaxAgeChanged with/without original.
 */
class TrustedClientDefaultMaxAgeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDefaultMaxAge creates a new instance with the DefaultMaxAge set
     * from a string value, and getDefaultMaxAge returns the primitive string.
     */
    public function testWithDefaultMaxAgeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultMaxAgeAccessorUnitTest();

        // Act
        $result = $holder->withDefaultMaxAge(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getDefaultMaxAge());
    }
    /**
     * Asserts that withdefaultMaxAge has access to the value object
     * from a string value, and getDefaultMaxAge returns the primitive string.
     */
    public function testWithDefaultMaxAgeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultMaxAgeAccessorUnitTest();

        // Act
        $result = $holder->withDefaultMaxAge(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->defaultMaxAge()->value());
    }
    public function testChangedDefaultMaxAge(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultMaxAgeAccessorUnitTest();
        $original = $holder->withDefaultMaxAge(1);
        $same = $holder->withDefaultMaxAge(1);
        $modified = $holder->withDefaultMaxAge(2);

        // Act
        $unchanged = $holder->isDefaultMaxAgeChanged();
        $withSame = $original->isDefaultMaxAgeChanged($same);
        $withDiferent = $original->isDefaultMaxAgeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientDefaultMaxAgeAccessorUnitTest
{
    use TrustedClientDefaultMaxAgeAccessor;
}
